// modules/api.js

const BASE_URL = 'https://weather.visualcrossing.com/VisualCrossingWebServices/rest/services/timeline/';
const API_KEY = 'T74DFCSK6R9XDJA8TRFRLL2QH';

export default async function fetchWeatherData(location) {
  console.log(`${BASE_URL}${location}?key=${API_KEY}`);
  try {
    const response = await fetch(`${BASE_URL}${location}?key=${API_KEY}`, { mode: 'cors' });
    if (!response.ok) {
      throw new Error(`API error: ${response.statusText}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.log(error);
    return null;
  }
}
