// modules/geolocation.js

export default function fetchGeoLocation() {
  return new Promise((resolve, reject) => {
    const options = {
      maximumAge: 0,
      enableHighAccuracy: false,
    };

    const success = (pos) => {
      const { coords } = pos; // same as const coords = pos.coords
      console.log(coords);
      resolve(coords);
    };

    const error = (err) => {
      console.error("❌ Geolocation Error:", err)
      reject(err);
    };

    navigator.geolocation.getCurrentPosition(success, error, options);
  });
}
